const phoneAppUrl = new URL('./', location.href).href;
document.querySelectorAll('[data-phone]').forEach(b=>b.addEventListener('click',()=>{dialog(`<h2>Ouvrir sur mon téléphone</h2><img class="qr-large" src="qr-application.png" alt="Flashcode vers l’application Ombaliz Mes besoins" width="300" height="300"><p>Scannez avec l’appareil photo de votre téléphone, puis touchez le lien proposé.</p><p><b>Pour le PDF :</b> complétez vos besoins sur votre téléphone, puis ouvrez « Mes petits pas » et « Télécharger mon rapport PDF ».</p><p class="phone-note">Vos réponses restent sur l’appareil où vous les avez saisies. Le flashcode ne transfère aucun bilan.</p><p><a href="${phoneAppUrl}">Ouvrir l’application</a></p><button id="copy-phone-link">Copier le lien</button> <a class="qr-download" href="qr-application.png" download="Flashcode-Ombaliz-Mes-besoins.png">Télécharger le flashcode</a><p id="phone-status" role="status"></p>`);document.querySelector('#copy-phone-link').onclick=async()=>{try{await navigator.clipboard.writeText(phoneAppUrl);document.querySelector('#phone-status').textContent='Lien copié.'}catch{document.querySelector('#phone-status').textContent='Copiez le lien affiché : '+phoneAppUrl}}}));